'use server'

import { revalidatePath } from 'next/cache'

/**
 * Toggles a user's notification preference and refreshes the current page.
 * 
 * @param userId - The ID of the user
 * @param currentPath - The path of the current page to refresh (e.g., passed from the client component using `usePathname()`)
 */
export async function toggleNotificationPreference(userId: string, currentPath: string) {
  // 1. Perform the database update to toggle the preference
  // await db.user.update({ ... })
  console.log(`Toggled notification preference for user: ${userId}`)

  // 2. Revalidate the current path to refresh the page without redirecting
  revalidatePath(currentPath)
}

